INSERT INTO birds (name_ko, name_sci, type, regions, season_start, season_end, rarity, description, silhouette_url) VALUES
('참새', 'Passer montanus', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','세종특별자치시','경상북도','경상남도','대구광역시','부산광역시','울산광역시','전라북도','전라남도','광주광역시','제주도'], NULL, NULL, 'common', '한국 전역에 서식하는 가장 흔한 텃새. 갈색과 흰색 줄무늬가 특징이며 인가 주변에서 주로 생활한다.', '/silhouette.svg'),
('까치', 'Pica serica', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','세종특별자치시','경상북도','경상남도','대구광역시','부산광역시','울산광역시','전라북도','전라남도','광주광역시'], NULL, NULL, 'common', '한국의 국조(國鳥). 흑백 대비가 뚜렷하며 나무 꼭대기에 둥지를 틀고 사람 가까이 산다.', '/silhouette.svg'),
('까마귀', 'Corvus corone', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '전신이 광택 있는 검은색인 대형 조류. 지능이 높고 사회성이 강하다.', '/silhouette.svg'),
('멧비둘기', 'Streptopelia orientalis', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','세종특별자치시','경상북도','경상남도','대구광역시','부산광역시','울산광역시','전라북도','전라남도','광주광역시','제주도'], NULL, NULL, 'common', '산과 도시 공원 모두에서 볼 수 있는 흔한 텃새. 목에 줄무늬 무늬가 있다.', '/silhouette.svg'),
('박새', 'Parus major', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','세종특별자치시','경상북도','경상남도','대구광역시','부산광역시','울산광역시','전라북도','전라남도','광주광역시','제주도'], NULL, NULL, 'common', '가슴의 검은 줄무늬가 특징인 작은 텃새. 나무 구멍에 둥지를 트는 산림성 조류.', '/silhouette.svg'),
('곤줄박이', 'Sittiparus varius', 'resident', ARRAY['서울특별시','경기도','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '주황색 배와 흑백 머리가 인상적인 산림성 텃새. 도토리를 저장하는 습성이 있다.', '/silhouette.svg'),
('오목눈이', 'Aegithalos caudatus', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '긴 꼬리와 둥그런 몸체가 특징인 소형 텃새. 겨울에 무리 지어 다닌다.', '/silhouette.svg'),
('동고비', 'Sitta europaea', 'resident', ARRAY['경기도','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '나무 줄기를 거꾸로 내려올 수 있는 특이한 능력을 가진 소형 조류.', '/silhouette.svg'),
('딱새', 'Phoenicurus auroreus', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','경상북도','경상남도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '수컷은 주황색 배와 검은 얼굴이 화려하다. 꼬리를 아래위로 흔드는 습성이 있다.', '/silhouette.svg'),
('직박구리', 'Hypsipetes amaurotis', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','경상북도','경상남도','대구광역시','부산광역시','울산광역시','전라북도','전라남도','광주광역시','제주도'], NULL, NULL, 'common', '귀 부분의 갈색 무늬와 날카로운 울음소리가 특징. 도시와 산림 경계에서 흔히 보인다.', '/silhouette.svg'),
('물까치', 'Cyanopica cyanus', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '하늘색 날개와 긴 꼬리가 아름다운 조류. 하천 주변 나무에서 무리 지어 서식한다.', '/silhouette.svg'),
('어치', 'Garrulus glandarius', 'resident', ARRAY['경기도','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '날개의 파란 무늬가 인상적인 까마귀과 조류. 도토리를 저장하는 숲속 텃새.', '/silhouette.svg'),
('굴뚝새', 'Troglodytes troglodytes', 'resident', ARRAY['강원도','경기도','충청북도','경상북도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '한국에서 가장 작은 새 중 하나. 꼬리를 세우고 큰 목소리로 지저귀는 특성이 있다.', '/silhouette.svg'),
('붉은머리오목눈이', 'Sinosuthora webbiana', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '붉은 갈색 머리와 줄무늬 몸통이 특징. 갈대밭이나 덤불에서 무리 생활을 한다.', '/silhouette.svg'),
('노랑턱멧새', 'Emberiza elegans', 'resident', ARRAY['경기도','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '노란 목과 검은 눈 무늬가 선명한 멧새. 산기슭 덤불에서 번식한다.', '/silhouette.svg'),
('황조롱이', 'Falco tinnunculus', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '도심 빌딩에서도 번식하는 작은 매. 제자리비행(호버링)으로 먹이를 찾는 습성이 있다.', '/silhouette.svg'),
('새홀리기', 'Falco subbuteo', 'migratory', ARRAY['경기도','강원도','충청북도','경상북도','전라북도'], 5, 9, 'common', '빠른 비행 속도로 잠자리와 소형 조류를 잡아먹는 소형 매. 여름 철새.', '/silhouette.svg'),
('붉은배새매', 'Accipiter soloensis', 'migratory', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], 4, 9, 'common', '가슴의 붉은 줄무늬가 특징인 소형 매. 논과 밭 주변 수림에서 번식한다.', '/silhouette.svg'),
('참매', 'Accipiter gentilis', 'resident', ARRAY['강원도','경기도','충청북도','경상북도','전라북도'], NULL, NULL, 'endangered_2', '강력한 사냥 능력을 가진 대형 맹금류. 울창한 산림에서 서식하며 개체 수가 적다.', '/silhouette.svg'),
('흰꼬리수리', 'Haliaeetus albicilla', 'migratory', ARRAY['경기도','인천광역시','강원도','충청남도','전라북도','전라남도','경상남도'], 10, 3, 'endangered_1', '날개 폭이 2m를 넘는 대형 독수리. 흰 꼬리가 특징이며 겨울철 강과 호수에서 월동한다.', '/silhouette.svg'),
('독수리', 'Aegypius monachus', 'migratory', ARRAY['경기도','강원도','충청남도','경상남도','전라남도'], 10, 3, 'endangered_2', '날개 폭 3m의 초대형 맹금류. 죽은 동물을 먹는 청소부 역할을 하며 겨울에 도래한다.', '/silhouette.svg'),
('두루미', 'Grus japonensis', 'migratory', ARRAY['경기도','강원도','경상북도'], 11, 3, 'endangered_1', '한국의 대표적인 겨울 철새. 붉은 이마와 흑백 몸통이 특징이며 철원 지역에서 월동한다.', '/silhouette.svg'),
('재두루미', 'Grus vipio', 'migratory', ARRAY['경기도','강원도','경상북도','전라북도'], 10, 3, 'endangered_2', '두루미보다 작으며 얼굴에 붉은 피부가 노출된 대형 조류. 철원과 순천만에서 월동.', '/silhouette.svg'),
('흑두루미', 'Grus monacha', 'migratory', ARRAY['전라남도','경상남도'], 10, 3, 'endangered_2', '흑색 몸통에 흰 목이 대비되는 중형 두루미. 순천만 갈대밭에서 월동하는 것으로 유명.', '/silhouette.svg'),
('저어새', 'Platalea minor', 'migratory', ARRAY['인천광역시','경기도','전라남도','경상남도','제주도'], 3, 10, 'endangered_1', '주걱 모양 부리가 특징인 국제적 멸종위기종. 인천 무인도에서 번식하는 세계적 희귀종.', '/silhouette.svg'),
('노랑부리저어새', 'Platalea leucorodia', 'migratory', ARRAY['인천광역시','전라남도','경상남도'], 10, 3, 'endangered_2', '저어새와 유사하지만 더 크고 부리 끝이 노란색. 겨울 철새로 서해안에서 월동.', '/silhouette.svg'),
('황새', 'Ciconia boyciana', 'migratory', ARRAY['충청남도','경기도','전라북도','전라남도'], 10, 3, 'endangered_1', '날개 폭 2m의 대형 조류. 과거 한국에서 번식했으나 현재는 겨울 철새로만 도래하는 극희귀종.', '/silhouette.svg'),
('큰기러기', 'Anser fabalis', 'migratory', ARRAY['경기도','인천광역시','강원도','충청남도','전라북도','전라남도','경상남도'], 10, 3, 'common', '대형 기러기로 겨울철 논밭과 습지에서 무리 지어 월동. ''V''자 편대 비행이 인상적.', '/silhouette.svg'),
('흰기러기', 'Anser caerulescens', 'migratory', ARRAY['인천광역시','경기도','전라남도'], 11, 2, 'common', '전신이 흰색인 기러기로 드물게 한국을 찾는 겨울 철새.', '/silhouette.svg'),
('오리', 'Anas platyrhynchos', 'migratory', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], 10, 3, 'common', '수컷의 초록 머리가 특징인 대표적인 겨울 철새 오리. 도심 하천에서도 흔히 관찰된다.', '/silhouette.svg'),
('청둥오리', 'Anas platyrhynchos', 'migratory', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], 10, 3, 'common', '가장 흔한 겨울 철새 오리. 수컷의 광택 있는 초록 머리가 특징이다.', '/silhouette.svg'),
('원앙', 'Aix galericulata', 'resident', ARRAY['경기도','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도'], NULL, NULL, 'common', '수컷의 화려한 깃털이 세계적으로 유명한 조류. 계곡 주변 나무 구멍에 둥지를 튼다.', '/silhouette.svg'),
('고방오리', 'Anas acuta', 'migratory', ARRAY['경기도','인천광역시','충청남도','전라북도','전라남도','경상남도'], 10, 3, 'common', '긴 꼬리가 특징인 날씬한 오리. 서해안 갯벌과 논에서 겨울을 보낸다.', '/silhouette.svg'),
('흰뺨검둥오리', 'Anas zonorhyncha', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','경상북도','경상남도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '뺨의 흰 무늬가 특징인 한국 고유 계통 오리. 도심 하천과 논에서 흔히 서식한다.', '/silhouette.svg'),
('논병아리', 'Tachybaptus ruficollis', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','경상북도','경상남도','전라북도','전라남도','제주도'], NULL, NULL, 'common', '가장 작은 논병아리류. 잠수 능력이 뛰어나며 연못과 저수지에서 서식한다.', '/silhouette.svg'),
('뿔논병아리', 'Podiceps cristatus', 'migratory', ARRAY['경기도','인천광역시','충청남도','전라북도','전라남도','경상남도'], 10, 3, 'common', '머리의 뿔 모양 장식 깃털이 인상적인 중형 논병아리. 겨울 바다와 큰 호수에서 월동.', '/silhouette.svg'),
('가마우지', 'Phalacrocorax carbo', 'migratory', ARRAY['서울특별시','경기도','인천광역시','강원도','충청남도','전라북도','전라남도','경상남도','제주도'], 10, 3, 'common', '날개를 펴고 말리는 독특한 행동이 특징인 대형 수조류. 강과 바다 모두에서 관찰된다.', '/silhouette.svg'),
('민물가마우지', 'Phalacrocorax niger', 'resident', ARRAY['경기도','강원도','충청북도','경상북도','전라북도','전라남도'], NULL, NULL, 'common', '내륙 하천과 저수지에서 번식하는 가마우지류. 군집 번식지를 형성한다.', '/silhouette.svg'),
('왜가리', 'Ardea cinerea', 'resident', ARRAY['서울특별시','경기도','인천광역시','강원도','충청북도','충청남도','대전광역시','경상북도','경상남도','대구광역시','부산광역시','전라북도','전라남도','광주광역시','제주도'], NULL, NULL, 'common', '날개 폭 2m의 대형 왜가리. 강가와 논에서 긴 다리로 서서 물고기를 낚아채는 대형 텃새.', '/silhouette.svg'),
('대백로', 'Ardea alba', 'migratory', ARRAY['경기도','인천광역시','충청남도','전라북도','전라남도','경상남도','제주도'], 4, 10, 'common', '전신이 흰색인 대형 백로. 번식기에 아름다운 장식 깃털(에그렛)이 발달한다.', '/silhouette.svg'),
('중백로', 'Ardea intermedia', 'migratory', ARRAY['경기도','충청남도','전라북도','전라남도','경상남도'], 4, 9, 'common', '대백로와 쇠백로의 중간 크기 백로. 논과 습지에서 여름을 보낸다.', '/silhouette.svg'),
('쇠백로', 'Egretta garzetta', 'migratory', ARRAY['서울특별시','경기도','인천광역시','강원도','충청남도','전라북도','전라남도','경상남도','제주도'], 4, 10, 'common', '작은 백로류로 노란 발가락이 특징. 논과 하천에서 흔히 볼 수 있는 여름 철새.', '/silhouette.svg'),
('황로', 'Bubulcus ibis', 'migratory', ARRAY['충청남도','전라북도','전라남도','경상남도','제주도'], 4, 9, 'common', '소나 말 옆에 붙어 다니며 먹이를 찾는 백로. 번식기에 머리와 가슴이 황갈색으로 변한다.', '/silhouette.svg'),
('해오라기', 'Nycticorax nycticorax', 'migratory', ARRAY['서울특별시','경기도','인천광역시','충청남도','전라북도','전라남도','경상남도'], 4, 10, 'common', '야행성 왜가리류로 주로 밤에 활동. 흑백의 대비가 선명하고 붉은 눈이 특징.', '/silhouette.svg'),
